-- TEST DATABASE ONLY: run only after confirming this is your isolated, empty test database.
-- Requires the Prisma schema to already exist. Refuses to import into non-empty tables.
-- Synthetic addresses use example.com; these are not real Gmail/KQ identities.
-- Test login: admin@example.com / Test1234! (all sample accounts share this test password).
-- isDemo is FALSE so the current app can display and score these records; database isolation is essential.

BEGIN;

DO $$
DECLARE
  table_name TEXT;
  table_has_rows BOOLEAN;
  required_tables TEXT[] := ARRAY['User', 'Profile', 'Skill', 'Interest', 'ProfileSkill', 'ProfileInterest', 'MentorshipRequest', 'ConnectionRequest', 'Feedback'];
BEGIN
  FOREACH table_name IN ARRAY required_tables LOOP
    IF to_regclass(format('public.%I', table_name)) IS NULL THEN
      RAISE EXCEPTION 'Required table public.% is missing. Apply the project schema to this test database first.', table_name;
    END IF;
    EXECUTE format('SELECT EXISTS (SELECT 1 FROM public.%I LIMIT 1)', table_name) INTO table_has_rows;
    IF table_has_rows THEN
      RAISE EXCEPTION 'Refusing demo import: public.% already contains rows. Use a separate empty test database.', table_name;
    END IF;
  END LOOP;
END $$;


